import{_ as a,c as s,o as t,ax as i}from"./chunks/framework.DHqKNX4U.js";const k=JSON.parse('{"title":"Upgrading to the Enterprise Edition","description":"","frontmatter":{},"headers":[],"relativePath":"enterprise/upgrade/guide.md","filePath":"enterprise/upgrade/guide.md"}'),n={name:"enterprise/upgrade/guide.md"};function o(r,e,h,l,p,d){return t(),s("div",null,e[0]||(e[0]=[i(`<h1 id="upgrading-to-the-enterprise-edition" tabindex="-1">Upgrading to the Enterprise Edition <a class="header-anchor" href="#upgrading-to-the-enterprise-edition" aria-label="Permalink to &quot;Upgrading to the Enterprise Edition&quot;">​</a></h1><p>This guide explains how to move an existing Open Archiver installation from the Open Source Edition to the Enterprise Edition.</p><p>The upgrade is done in place. You only need to replace the Docker image and add the license key in the environment variable; your database, archived emails, search index and settings remain as they are. Nothing needs to be re-imported, and users, roles and ingestion sources keep working without changes.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What needs to change</th><th>What stays the same</th></tr></thead><tbody><tr><td>The application image (<code>-enterprise</code> tag)</td><td>The PostgreSQL database and all archived emails</td></tr><tr><td>A license key in your <code>.env</code> file</td><td>Stored files (local disk or S3)</td></tr><tr><td>Optionally, the SMTP journaling port and settings</td><td>The Meilisearch index, Valkey and Tika services</td></tr><tr><td></td><td>Your encryption keys and all other settings</td></tr></tbody></table><p>The Enterprise image contains everything in the Open Source Edition, so all existing features continue to work after the upgrade.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><h3 id="your-license-key" tabindex="-1">Your license key <a class="header-anchor" href="#your-license-key" aria-label="Permalink to &quot;Your license key&quot;">​</a></h3><p>You receive a license key when you purchase the Enterprise Edition. It is a long text string (a signed JWT). Keep it available for step 2.</p><h3 id="choose-the-enterprise-release" tabindex="-1">Choose the Enterprise release <a class="header-anchor" href="#choose-the-enterprise-release" aria-label="Permalink to &quot;Choose the Enterprise release&quot;">​</a></h3><p>Upgrade to the latest Enterprise release by using the -enterprise tag Docker images (see details below). If you need to pin a specific older Enterprise release instead, contact us first so we can confirm it is compatible with your current database.</p><h3 id="network-access" tabindex="-1">Network access <a class="header-anchor" href="#network-access" aria-label="Permalink to &quot;Network access&quot;">​</a></h3><p>Enterprise deployments contact the license server at <code>https://openarchiver.com</code> once a day and when the application starts to check license validity. Allow outbound HTTPS (port 443) from the Open Archiver server to <code>openarchiver.com</code>. No private data from your archive is sent to the server. We only report seat numbers and instance version. See <a href="#license-checks-and-offline-operation">License checks and offline operation</a> for what is sent.</p><h2 id="step-1-back-up" tabindex="-1">Step 1: Back up <a class="header-anchor" href="#step-1-back-up" aria-label="Permalink to &quot;Step 1: Back up&quot;">​</a></h2><p>Back up before any upgrade. Run these commands from the directory that contains your <code>docker-compose.yml</code>.</p><ol><li><p><strong>Database:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;pg_dump -U &quot;$POSTGRES_USER&quot; &quot;$POSTGRES_DB&quot;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open-archiver-db.sql</span></span></code></pre></div></li><li><p><strong>Optionally, stored emails and attachments.</strong></p></li></ol><blockquote><p>This step is <strong>optional</strong> because upgrade to the Enterprise Edition generally doesn&#39;t break archived emails and files. This step may consume a large storage space.</p></blockquote><p>If you use local storage with the default named volume, copy the volume to an archive file. The volume name starts with your Compose project name, usually the name of the directory, for example <code>open-archiver_archiver-data</code>:</p><pre><code>\`\`\`bash
docker volume ls | grep archiver-data
docker run --rm -v open-archiver_archiver-data:/data -v &quot;$PWD&quot;:/backup alpine \\
    tar czf /backup/archiver-data.tgz -C /data .
\`\`\`

If you store files in S3, the bucket is not changed by the upgrade.
</code></pre><ol start="3"><li><strong>Configuration.</strong> Copy your <code>.env</code> file to a safe place. It contains <code>STORAGE_ENCRYPTION_KEY</code> and <code>ENCRYPTION_KEY</code>. Without them, encrypted emails and stored credentials cannot be read, by you or by anyone else.</li></ol><h2 id="step-2-add-the-license-key" tabindex="-1">Step 2: Add the license key <a class="header-anchor" href="#step-2-add-the-license-key" aria-label="Permalink to &quot;Step 2: Add the license key&quot;">​</a></h2><p>Open your <code>.env</code> file and add the license key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --- License (Enterprise only) ---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OA_LICENSE_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">eyJhbGciOiJFUzI1NiIsInR5cCI6IkpXVCJ9...</span></span></code></pre></div><p>Paste the whole key on one line.</p><div class="tip custom-block"><p class="custom-block-title">Alternatively, you can use a license file instead if you prefer not to keep the license key in <code>.env</code>. Save the license key as a file named <code>license.jwt</code> and mount it into the container:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    open-archiver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;./license.jwt:/app/packages/enterprise/dist/modules/license/license.jwt:ro&#39;</span></span></code></pre></div><p><code>OA_LICENSE_KEY</code> in the <code>.env</code> file takes precedence when both are present.</p></div><h2 id="step-3-switch-to-the-enterprise-image" tabindex="-1">Step 3: Switch to the Enterprise image <a class="header-anchor" href="#step-3-switch-to-the-enterprise-image" aria-label="Permalink to &quot;Step 3: Switch to the Enterprise image&quot;">​</a></h2><p>Open <code>docker-compose.yml</code> and change the image of the <code>open-archiver</code> service:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    open-archiver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Before: image: logiclabshq/open-archiver:latest</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logiclabshq/open-archiver:latest-enterprise</span></span></code></pre></div><p><code>latest-enterprise</code> always points to the newest Enterprise release. To pin a version, use the release tag with the <code>-enterprise</code> suffix instead, for example <code>logiclabshq/open-archiver:v1.6.0-enterprise</code>.</p><p>Leave the other services (<code>postgres</code>, <code>valkey</code>, <code>meilisearch</code>, <code>tika</code>) unchanged.</p><h2 id="step-4-set-up-smtp-journaling-optional" tabindex="-1">Step 4: Set up SMTP journaling (optional) <a class="header-anchor" href="#step-4-set-up-smtp-journaling-optional" aria-label="Permalink to &quot;Step 4: Set up SMTP journaling (optional)&quot;">​</a></h2><p>Skip this step if you do not plan to use <a href="./../journaling/guide.html">SMTP journaling</a>. You can also set it up later.</p><ol><li><p>Publish the journaling port by adding it to the <code>ports</code> of the <code>open-archiver</code> service:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    open-archiver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3000:\${PORT_FRONTEND:-3000}&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Frontend</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;25:\${SMTP_JOURNALING_PORT:-2525}&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # SMTP journaling listener</span></span></code></pre></div></li><li><p>Add the journaling settings to <code>.env</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --- SMTP Journaling (Enterprise only) ---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SMTP_JOURNALING_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2525</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SMTP_JOURNALING_DOMAIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">journal.yourdomain.com</span></span></code></pre></div></li><li><p>Create the MX record and open port 25 in your firewall as described in the <a href="./../journaling/guide.html">SMTP Journaling guide</a>.</p></li></ol><h2 id="step-5-restart-with-the-new-image" tabindex="-1">Step 5: Restart with the new image <a class="header-anchor" href="#step-5-restart-with-the-new-image" aria-label="Permalink to &quot;Step 5: Restart with the new image&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Database migrations run automatically when the container starts. No manual step is needed.</p><h2 id="step-6-verify-the-upgrade" tabindex="-1">Step 6: Verify the upgrade <a class="header-anchor" href="#step-6-verify-the-upgrade" aria-label="Permalink to &quot;Step 6: Verify the upgrade&quot;">​</a></h2><ol><li><p><strong>Check the logs.</strong> The startup log should contain a line confirming the license:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open-archiver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> license</span></span></code></pre></div><p>Expected: <code>Enterprise license successfully verified for: &lt;your company name&gt;</code>.</p></li><li><p><strong>Open the License Status page.</strong> Sign in as a Super Admin and go to <strong>Admin → License Status</strong>. The page shows your company name, the license status, the seats in your plan and the enabled features.</p></li><li><p><strong>Open an Enterprise page.</strong> In the Open Source Edition, pages such as <strong>Compliance → Audit Log</strong> show an &quot;Enterprise Edition&quot; notice. After the upgrade, they show the feature itself. The Enterprise features are found here:</p><table tabindex="0"><thead><tr><th>Menu</th><th>Features</th></tr></thead><tbody><tr><td>Archive</td><td>SMTP Journaling</td></tr><tr><td>Compliance</td><td>Audit Log, Retention Policies, Retention Labels, Legal Holds</td></tr><tr><td>Admin</td><td>Security Policy, Single Sign-On, License Status</td></tr></tbody></table></li></ol><h2 id="license-checks-and-offline-operation" tabindex="-1">License checks and offline operation <a class="header-anchor" href="#license-checks-and-offline-operation" aria-label="Permalink to &quot;License checks and offline operation&quot;">​</a></h2><p>Once a day, and when the application starts, Open Archiver contacts <code>https://openarchiver.com</code> to verify the license. The request contains the license identifier, a deployment identifier, the software version, the number of seats and the breakdown behind that number. No email content, email addresses, names or attachments are sent. See <a href="./../seats/guide.html">Seat Counting</a> for details.</p><p>If the license server cannot be reached, Enterprise features keep working for the offline grace period (14 days unless your license says otherwise). After that, Enterprise features are switched off until the next successful check. The archive itself, search, ingestion and all Open Source Edition features keep working throughout. The license is checked again at the next daily check; you can also click <strong>Revalidate License</strong> on the License Status page to check immediately.</p><p>For large deployments in air-gapped environments, license reporting can be disabled so the archive never needs to contact the license server. Contact us to enable this for your license.</p><h2 id="several-application-servers" tabindex="-1">Several application servers <a class="header-anchor" href="#several-application-servers" aria-label="Permalink to &quot;Several application servers&quot;">​</a></h2><p>If you run more than one Open Archiver application server against the same database, upgrade all of them to the same Enterprise image and give all of them the same license key. They share one database and therefore count as one deployment with one seat count.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>The log shows <code>License key not found.</code></strong> The key is missing or empty. Check that <code>OA_LICENSE_KEY</code> is set in the <code>.env</code> file the container uses, or that <code>license.jwt</code> is mounted at the path shown in step 2. Restart the container after changing either.</p><p><strong>Enterprise pages still show the &quot;Enterprise Edition&quot; notice.</strong> The container is still running the open-source image. Check the image with <code>docker compose ps</code> and run <code>docker compose pull</code> and <code>docker compose up -d</code> again.</p><p><strong>The License Status page shows &quot;Offline grace remaining&quot;.</strong> The license server has not been reached recently; <strong>Last verified</strong> shows when it last succeeded. Check that the server can open outbound HTTPS connections to <code>openarchiver.com</code>, then click <strong>Revalidate License</strong>. Enterprise features keep working until the grace period runs out.</p><p><strong>The License Status page warns that the license key is used on more than one instance.</strong> Each license key belongs to one deployment. Make sure no other installation, such as a test system or a copy, runs with the same key, or contact your account manager to add instances.</p><h2 id="switching-back-to-the-open-source-edition" tabindex="-1">Switching back to the Open Source Edition <a class="header-anchor" href="#switching-back-to-the-open-source-edition" aria-label="Permalink to &quot;Switching back to the Open Source Edition&quot;">​</a></h2><p>If you need to return to the Open Source Edition, contact us first so we can tell you which open-source release is compatible with your database. Then change the image back to that release, remove <code>OA_LICENSE_KEY</code>, and restart. Your archive and all data remain intact, and the Enterprise data (policies, labels, holds, audit log) stays in the database for a later upgrade.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Without the Enterprise Edition, Enterprise rules are no longer applied. Legal holds no longer prevent deletion, retention policies and labels are no longer enforced, and journaled emails are no longer received. If you rely on legal holds, make sure deletion stays disabled (<code>ENABLE_DELETION</code> not set to <code>true</code>) while you run the Open Source Edition.</p></div>`,52)]))}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
